  void BuildChart(){
   body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});body.RowDefinitions.Add(new RowDefinition());body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});
   Action redraw=null;var tools=new DockPanel{Margin=new Thickness(0,0,0,12)};var right=Ui.Stack(true);DockPanel.SetDock(right,Dock.Right);var status=new MultiPicker("状态",Model.Statuses.Select(s=>new Choice{Id=s,Label=s}),statusFilters);status.Changed=()=>{statusFilters=new HashSet<string>(status.Selected);if(redraw!=null)redraw();};right.Children.Add(status);var arrange=Ui.Button("＋ 安排现有任务",()=>Schedule(null));arrange.Margin=new Thickness(8,0,0,0);right.Children.Add(arrange);tools.Children.Add(right);
   var dates=Ui.Stack(true);var caption=Ui.Stack();caption.MinWidth=156;caption.Children.Add(Ui.Text(viewStart.ToString("yyyy 年 M 月"),15,null,true));caption.Children.Add(Ui.Text(viewStart.ToString("MM.dd")+" — "+viewStart.AddDays(days-1).ToString("MM.dd"),11,Ui.Muted));dates.Children.Add(caption);var prev=Ui.Button("‹",()=>{viewStart=viewStart.AddDays(-7);RebuildBody();});prev.Padding=new Thickness(11,5,11,5);dates.Children.Add(prev);var today=Ui.Button("今天",()=>{viewStart=Model.Monday(DateTime.Today);RebuildBody();});today.Margin=new Thickness(5,0,5,0);today.Padding=new Thickness(9,5,9,5);dates.Children.Add(today);var next=Ui.Button("›",()=>{viewStart=viewStart.AddDays(7);RebuildBody();});next.Padding=new Thickness(11,5,11,5);dates.Children.Add(next);tools.Children.Add(dates);body.Children.Add(tools);
   var chart=new GanttView(store.Data,ChartTasks(),viewStart,days,groupPeople);redraw=()=>{chart.Tasks=ChartTasks();chart.Height=64+Math.Max(chart.Tasks.Count,4)*62+38;chart.InvalidateVisual();};chart.TaskClicked=id=>Schedule(id);var scroll=new ScrollViewer{Content=chart,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};scroll.SizeChanged+=(s,e)=>chart.Width=Math.Max(chart.MinWidth,Math.Max(0,scroll.ActualWidth-19));chart.Width=Math.Max(chart.MinWidth,Math.Max(600,Width-300));var border=Ui.Card(scroll,0);Grid.SetRow(border,1);body.Children.Add(border);
   var bottom=new DockPanel{Margin=new Thickness(0,11,0,4)};var settings=Ui.Stack(true);DockPanel.SetDock(settings,Dock.Right);var group=new ComboBox{ItemsSource=new[]{"按人员分组","按任务展示"},SelectedIndex=groupPeople?0:1,MinWidth=122,MinHeight=31};group.SelectionChanged+=(s,e)=>{groupPeople=group.SelectedIndex==0;RebuildBody();};settings.Children.Add(group);var daySelect=new ComboBox{ItemsSource=new[]{"7 天","14 天","28 天","31 天"},SelectedIndex=days==7?0:days==14?1:days==28?2:3,Width=83,Margin=new Thickness(8,0,0,0),MinHeight=31};daySelect.SelectionChanged+=(s,e)=>{days=new[]{7,14,28,31}[daySelect.SelectedIndex];RebuildBody();};settings.Children.Add(daySelect);bottom.Children.Add(settings);bottom.Children.Add(Ui.Text("周末已标注 · 点击甘特条，可多选现有任务并替换排期。",11,Ui.Muted));Grid.SetRow(bottom,2);body.Children.Add(bottom);
