  void BuildNoProject(){var p=Ui.Stack();p.VerticalAlignment=VerticalAlignment.Center;p.HorizontalAlignment=HorizontalAlignment.Center;p.MaxWidth=420;p.Margin=new Thickness(24);var icon=Ui.Text("▱",46,Ui.Brand);icon.HorizontalAlignment=HorizontalAlignment.Center;p.Children.Add(icon);var title=Ui.Text("还没有项目",23,null,true);title.HorizontalAlignment=HorizontalAlignment.Center;title.Margin=new Thickness(0,13,0,10);p.Children.Add(title);var note=Ui.Text("新建一个项目开始工作，或从左侧导入已有的全部数据。",13,Ui.Muted);note.TextAlignment=TextAlignment.Center;p.Children.Add(note);var add=Ui.Button("＋ 新建第一个项目",()=>projectPicker.AddNew(),true);add.HorizontalAlignment=HorizontalAlignment.Center;add.Margin=new Thickness(0,23,0,0);p.Children.Add(add);body.Children.Add(Ui.Card(p,0));}
  void RebuildBody(){body.Children.Clear();body.RowDefinitions.Clear();if(store.Data.Projects.Count==0)BuildNoProject();else if(gantt)BuildChart();else BuildTasks();}
  Grid TaskRowGrid(){var g=new Grid();foreach(double w in new[]{42.0,15.0,26.0,17.0})g.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(w,GridUnitType.Star)});return g;}
  void BuildTasks(){
   body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});body.RowDefinitions.Add(new RowDefinition());var filters=Ui.Stack(true);filters.Margin=new Thickness(0,0,0,12);foreach(var s in new[]{"全部"}.Concat(Model.Statuses)){string local=s;var b=Ui.Button(s,()=>{listStatus=local;RebuildBody();});b.Padding=new Thickness(10,6,10,6);b.BorderThickness=new Thickness(0);b.Background=s==listStatus?Ui.BrandSoft:Ui.Bg;b.Foreground=s==listStatus?Ui.Brand:Ui.Muted;b.Margin=new Thickness(0,0,4,0);filters.Children.Add(b);}body.Children.Add(filters);
   var dock=new DockPanel();var header=TaskRowGrid();header.Height=44;header.Background=Ui.Bg;int col=0;foreach(var label in new[]{"任务名称","负责人","计划时间","状态"}){var t=Ui.Text(label,12,Ui.Muted);t.Margin=new Thickness(15,0,7,0);Grid.SetColumn(t,col++);header.Children.Add(t);}DockPanel.SetDock(header,Dock.Top);dock.Children.Add(header);
   var rows=Ui.Stack();var items=ProjectTasks().Where(t=>listStatus=="全部"||t.Status==listStatus).ToList();foreach(var t in items){var task=t;var row=TaskRowGrid();row.MinHeight=70;var namePanel=Ui.Stack();namePanel.VerticalAlignment=VerticalAlignment.Center;namePanel.Margin=new Thickness(15,9,10,9);var name=Ui.Button("",()=>{Dialogs.Detail(this,store,task.Id);Refresh();});name.Content=Ui.Ellipsis(t.Name,13,null,true);name.HorizontalContentAlignment=HorizontalAlignment.Left;name.Padding=new Thickness(0);name.BorderThickness=new Thickness(0);namePanel.Children.Add(name);namePanel.Children.Add(Ui.Text(t.InGantt?"已纳入排期":"未纳入当前排期",11,Ui.Muted));row.Children.Add(namePanel);var person=Ui.Ellipsis(Model.PersonName(store.Data,t.PersonId),12);person.Margin=new Thickness(15,0,8,0);Grid.SetColumn(person,1);row.Children.Add(person);var range=Ui.Ellipsis(Model.IsDate(t.Start)?Model.Parse(t.Start).ToString("MM.dd")+" — "+Model.Parse(t.End).ToString("MM.dd"):"尚未安排",12,Ui.Muted);range.ToolTip=Model.Range(t);range.Margin=new Thickness(15,0,8,0);Grid.SetColumn(range,2);row.Children.Add(range);var status=Ui.Button("",()=>{Dialogs.TaskEditor(this,store,task.Id);Refresh();});status.Content=Ui.Badge(t.Status);status.HorizontalAlignment=HorizontalAlignment.Left;status.Background=Brushes.Transparent;status.BorderThickness=new Thickness(0);status.Padding=new Thickness(0);status.Margin=new Thickness(15,0,7,0);Grid.SetColumn(status,3);row.Children.Add(status);rows.Children.Add(new Border{Child=row,BorderBrush=Ui.Line,BorderThickness=new Thickness(0,0,0,1)});}
   if(items.Count==0){var empty=Ui.Text("暂无此状态的任务。点击“新建任务”开始。",14,Ui.Muted);empty.Margin=new Thickness(25,55,25,55);rows.Children.Add(empty);}dock.Children.Add(new ScrollViewer{Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});var card=Ui.Card(dock,0);Grid.SetRow(card,1);body.Children.Add(card);
  }
  void NewTaskOrProject(){if(store.Data.Projects.Count==0){projectPicker.AddNew();return;}Dialogs.TaskEditor(this,store,null);Refresh();}
  void Schedule(string id){if(ProjectTasks().Count==0){MessageBox.Show(this,"当前项目还没有任务，请先新建任务。","老秦进度管理软件");return;}var r=Dialogs.Schedule(this,store,id);if(r!=null){foreach(var s in r.Statuses)statusFilters.Add(s);viewStart=Model.Monday(r.Start);}Refresh();}
  void Export(){if(store.Data.Projects.Count==0){MessageBox.Show(this,"暂无项目，请先新建项目。全部数据仍可从左侧导出。","老秦进度管理软件");return;}Dialogs.Export(this,store,ChartTasks(),viewStart,viewStart.AddDays(days-1));}
  void Key(object sender,KeyEventArgs e){if((Keyboard.Modifiers&ModifierKeys.Control)==ModifierKeys.Control&&e.Key==System.Windows.Input.Key.N){NewTaskOrProject();e.Handled=true;}if((Keyboard.Modifiers&ModifierKeys.Control)==ModifierKeys.Control&&e.Key==System.Windows.Input.Key.E){Export();e.Handled=true;}}
 }
